import pytest
from statistics import median as ref_median

from hypothesis import given, strategies as st

from median import median


@given(st.lists(st.integers(), min_size=1))
def test_matches_statistics_median(xs):
    # Property 1: agrees with the reference implementation.
    assert median(xs) == ref_median(xs)


@given(st.lists(st.integers(), min_size=1))
def test_median_within_bounds(xs):
    # Property 2: median is between min and max.
    assert min(xs) <= median(xs) <= max(xs)


@given(st.lists(st.integers(), min_size=1), st.data())
def test_median_permutation_invariant(xs, data):
    # Property 3: invariant under shuffling (drawn permutation).
    perm = data.draw(st.permutations(xs))
    assert median(xs) == median(perm)


def test_empty_raises():
    with pytest.raises(ValueError):
        median([])

